/**
 * The domain's own `Bucket` type: a plain string literal union, compatible
 * with the `bucket` enum generated by Prisma but intentionally not imported
 * from it, so this module stays usable without the ORM.
 */
export type Bucket = "needs" | "wants" | "savings";

export const BUCKET_RATIOS: Record<Bucket, number> = {
  needs: 0.5,
  wants: 0.3,
  savings: 0.2,
};

export interface BucketSplit {
  needs: number;
  wants: number;
  savings: number;
}

const HUNDRED = BigInt(100);

/**
 * Splits an income (in cents) into the 50/30/20 buckets. `needs` and `wants`
 * are floored shares of the income; `savings` absorbs the rounding
 * remainder, so the three always sum back to the original income exactly.
 *
 * Uses BigInt for the share calculation instead of floating-point
 * multiplication/division: money math must never round a share up by a
 * cent due to binary floating-point imprecision. (BigInt literal syntax
 * like `50n` needs ES2020; this project's tsconfig targets ES2017, so the
 * `BigInt(...)` constructor is used instead — it works at any target.)
 */
export function splitIncome(incomeCents: number): BucketSplit {
  const income = BigInt(incomeCents);
  const needs = Number((income * BigInt(50)) / HUNDRED);
  const wants = Number((income * BigInt(30)) / HUNDRED);
  const savings = incomeCents - needs - wants;
  return { needs, wants, savings };
}
